function CatHouseExploreRootTaskRefresh:ResetInfo()
    local catHouseHomeDojo = CatHouseExploreMgr:GetCatHouseHomeDojo()
    local exploreRefreshTimes = checkNumber(catHouseHomeDojo.exploreRefreshTimes)
    KTool.SetActive(self.RecoveryTime.gameObject, not IsNull(CatHouseExploreMgr.timerTaskRefresh) and  exploreRefreshTimes < CatHouseExploreMgr.EXPLORE_REFRESH_TIME_MAX)
    if not IsNull(CatHouseExploreMgr.timerTaskRefresh) then
        self.TextTime.text = CfUtils.GetTimeHMS(checkNumber(CatHouseExploreMgr.timerTaskRefresh.CountTimes))
        CatHouseExploreMgr.timerTaskRefresh.OnCd = function(count)
            if (not IsNull(self.controller) and not IsNull(self.TextTime)) then
                if count >= 0 then
                    self.TextTime.text = CfUtils.GetTimeHMS(count)
                end
            end
        end
    end
    self.TextTimeRefresh.text = string.format("<color=#00f2e6><size=42>%d</size></color>/%d",exploreRefreshTimes, CatHouseExploreMgr.EXPLORE_REFRESH_TIME_MAX)
    
    local _functionAddTimes = function()
        local _setBtnInteractiveStatus = function(bool)
            self.BtnAdd.enabled = checkBool(bool)
        end
        local _funcSure = function()
            CatHouseExploreMgr:CatHouseExploreRefreshTimesBuy(function()
                CatHouseExploreMgr:UpdateTaskRefreshTimes(checkNumber(catHouseHomeDojo.exploreRefreshTimes) + 1)
                _setBtnInteractiveStatus(true)
                self:ResetInfo()
            end)
        end
        local _funcCancel = function()
            _setBtnInteractiveStatus(true)
        end
        local _getTitle = function()
            local goodsId = CatHouseExploreMgr.EXPLORE_REFRESH_GOODS_ID
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            local goodsName = checkString(goodsVo.name)
            return localize("是否消耗_num1_个_num2_立刻获得1次刷新次数?", { _num1_ = checkNumber(CatHouseExploreMgr.EXPLORE_REFRESH_GOODS_NUM), _num2_ = goodsName })
        end
        _setBtnInteractiveStatus(false)
        GameUtils.SecondConfirm(_getTitle(), _funcSure, _funcCancel, nil,nil,nil, true)
    end
    local _functionSignTimesFull = function()
        GameUtils.Toast(localize("刷新次数已达上限"))
    end
    SetButtonAction(self.BtnAdd.gameObject,exploreRefreshTimes >= CatHouseExploreMgr.EXPLORE_REFRESH_TIME_MAX and _functionSignTimesFull or _functionAddTimes)
end

return CatHouseExploreRootTaskRefresh

